"""Partition to K Equal Sum Subsets — fill one bucket at a time.

Sorting descending fails fast, and skipping a candidate that leaves a bucket
exactly empty or exactly full prunes the symmetric branches.

Time: O(k * 2^n)   Space: O(n)
"""
from typing import List


class Solution:
    def canPartitionKSubsets(self, nums: List[int], k: int) -> bool:
        total = sum(nums)
        if total % k:
            return False
        target = total // k
        nums.sort(reverse=True)
        if nums[0] > target:
            return False
        used = [False] * len(nums)

        def walk(start: int, current: int, buckets: int) -> bool:
            if buckets == 1:
                return True
            if current == target:
                return walk(0, 0, buckets - 1)
            prev = -1
            for i in range(start, len(nums)):
                if used[i] or current + nums[i] > target or nums[i] == prev:
                    continue
                used[i] = True
                if walk(i + 1, current + nums[i], buckets):
                    return True
                used[i] = False
                prev = nums[i]
                if current == 0:      # this number can never start a bucket
                    return False
            return False

        return walk(0, 0, k)
